import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds,
  evaluateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds against evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const validThresholds = validateThresholds(
      { exact_match: 0.5, toxicity: 0.8 },
      evaluations
    );
    expect(validThresholds.valid).toBe(true);
    expect(validThresholds.errors.length).toBe(0);

    const invalidThresholds = validateThresholds(
      { unknown_metric: 0.5 },
      evaluations
    );
    expect(invalidThresholds.valid).toBe(false);
    expect(invalidThresholds.errors.length).toBeGreaterThan(0);
  });

  it('evaluates thresholds and marks pass/fail', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const result = evaluateThresholds(
      { exact_match: 0.5, toxicity: 0.95 },
      evaluations
    );
    expect(result.thresholds).toHaveLength(2);

    const exactMatch = result.thresholds.find((t) => t.metric === 'exact_match');
    expect(exactMatch.passed).toBe(true);
    expect(exactMatch.min).toBe(0.5);

    const toxicity = result.thresholds.find((t) => t.metric === 'toxicity');
    expect(toxicity.passed).toBe(true);
  });

  it('fails threshold when metric score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'world']
    });

    const result = evaluateThresholds(
      { exact_match: 0.9 },
      evaluations
    );
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
    expect(result.thresholds[0].score).toBeLessThan(0.9);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });

    const result = evaluateThresholds(
      { exact_match: 0.5 },
      evaluations
    );
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
    expect(result.thresholds[0].score).toBeNull();
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].metric).toBe('exact_match');
    expect(report.thresholds[0].min).toBe(0.5);
    expect(report.thresholds[0].passed).toBe(true);
  });

  it('includes thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('PASS');
  });

  it('marks report as not passed when threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });

    expect(report.passed).toBe(false);
  });
});

